Diff summary:
- src/revenue/calculateStandardRevenue.js
  - Added calculateStandardRevenue(order) implementation
  - Validates inputs: unitPrice >= 0, quantity is non-negative integer, discountRate between 0 and 1
  - Computes subtotal = unitPrice * quantity
  - Computes discount = subtotal * discountRate
  - Computes revenue = subtotal - discount
  - Rounds final revenue to 2 decimals
  - Exports pure function with no side effects

- test/revenue/calculateStandardRevenue.test.js
  - Added tests for normal case, zero quantity, zero discount, max discount, invalid negative price, invalid quantity, invalid discount bounds, and rounding behavior

Representative patch:
--- a/src/revenue/calculateStandardRevenue.js
+++ b/src/revenue/calculateStandardRevenue.js
+export function calculateStandardRevenue(order) {
+  const { unitPrice, quantity, discountRate = 0 } = order;
+
+  if (typeof unitPrice !== 'number' || Number.isNaN(unitPrice) || unitPrice < 0) {
+    throw new Error('unitPrice must be a non-negative number');
+  }
+  if (!Number.isInteger(quantity) || quantity < 0) {
+    throw new Error('quantity must be a non-negative integer');
+  }
+  if (typeof discountRate !== 'number' || Number.isNaN(discountRate) || discountRate < 0 || discountRate > 1) {
+    throw new Error('discountRate must be a number between 0 and 1');
+  }
+
+  const subtotal = unitPrice * quantity;
+  const discount = subtotal * discountRate;
+  const revenue = subtotal - discount;
+
+  return Math.round(revenue * 100) / 100;
+}

