+export type RevenueInput = {
+  unitPriceCents: number;
+  quantity: number;
+  discountCents?: number;
+  refundedCents?: number;
+};
+
+export type RevenueResult = {
+  grossCents: number;
+  netCents: number;
+};
+
+export function calculateStandardRevenue(input: RevenueInput): RevenueResult {
+  const {
+    unitPriceCents,
+    quantity,
+    discountCents = 0,
+    refundedCents = 0,
+  } = input;
+
+  if (!Number.isInteger(unitPriceCents) || unitPriceCents < 0) {
+    throw new Error('unitPriceCents must be a non-negative integer');
+  }
+
+  if (!Number.isInteger(quantity) || quantity < 0) {
+    throw new Error('quantity must be a non-negative integer');
+  }
+
+  if (!Number.isInteger(discountCents) || discountCents < 0) {
+    throw new Error('discountCents must be a non-negative integer');
+  }
+
+  if (!Number.isInteger(refundedCents) || refundedCents < 0) {
+    throw new Error('refundedCents must be a non-negative integer');
+  }
+
+  const grossCents = unitPriceCents * quantity;
+  const discountedCents = grossCents - discountCents;
+  const netCents = Math.max(0, discountedCents - refundedCents);
+
+  return {
+    grossCents,
+    netCents,
+  };
+}

