+export interface RevenueInput {
+  amountCents: number;
+  currency: string;
+  source: string;
+}
+
+export interface RevenueRecord extends RevenueInput {
+  recognizedAt: string;
+}
+
+const SUPPORTED_CURRENCIES = new Set(["USD", "EUR", "GBP"]);
+
+export function validateRevenueInput(input: RevenueInput): void {
+  if (!Number.isInteger(input.amountCents) || input.amountCents < 0) {
+    throw new Error("amountCents must be a non-negative integer");
+  }
+
+  if (!SUPPORTED_CURRENCIES.has(input.currency)) {
+    throw new Error("currency is not supported");
+  }
+
+  if (input.source.trim().length === 0) {
+    throw new Error("source is required");
+  }
+}
+
+export function recognizeRevenue(
+  input: RevenueInput,
+  recognizedAt: string = new Date().toISOString()
+): RevenueRecord {
+  validateRevenueInput(input);
+
+  return {
+    ...input,
+    source: input.source.trim(),
+    recognizedAt,
+  };
+}
